<template><AppLayout><div class="mx-auto max-w-3xl space-y-5"><RouterLink to="/supplier/accounts" class="text-sm text-primary-600">← {{ t('marketplace.accounts') }}</RouterLink><div v-if="loading" class="card p-6">{{ t('marketplace.loading') }}</div><div v-else-if="error && !account" class="card p-6" role="alert">{{ t('marketplace.loadFailed') }} <button class="text-primary-600 underline" @click="load">{{ t('marketplace.retry') }}</button></div><template v-else-if="account"><div class="card space-y-4 p-6"><h1 class="text-xl font-semibold">{{ account.name }}</h1><div class="grid gap-3 text-sm sm:grid-cols-2"><p>{{ t('marketplace.provider') }}: {{ account.platform }} / {{ account.type }}</p><p>{{ t('marketplace.reviewStatus') }}: {{ account.offer.review_status }}</p><p>{{ t('marketplace.healthStatus') }}: {{ account.credential_status }}</p><p>{{ t('marketplace.currentRequests') }}: {{ account.current_concurrency }}</p></div><p v-if="readOnly" class="text-sm text-amber-600">{{ t('marketplace.readOnly') }}</p></div><form class="card space-y-4 p-6" @submit.prevent="save"><h2 class="font-semibold">{{ t('marketplace.configuration') }}</h2><label class="block text-sm">{{ t('marketplace.accountName') }}<input v-model="name" required class="input mt-1 w-full" :disabled="readOnly" /></label><fieldset :disabled="readOnly || !provider"><legend class="text-sm">{{ t('marketplace.allowedModels') }}</legend><label v-for="model in provider?.models || account.offer.allowed_models" :key="model" class="mr-4 inline-flex items-center gap-1 text-sm"><input v-model="models" type="checkbox" :value="model" />{{ model }}</label></fieldset><AccountConcurrencyForm v-model="concurrency" :max="options?.max_supplier_concurrency || account.concurrency" :disabled="readOnly || !options" /><p v-if="!options" class="text-sm text-amber-600">{{ t('marketplace.optionsUnavailable') }}</p><p v-if="conflict" role="alert" class="text-sm text-amber-600">{{ t('marketplace.versionConflict') }} <button type="button" class="underline" @click="refreshVersion">{{ t('marketplace.refreshVersion') }}</button></p><p v-if="error" role="alert" class="text-sm text-red-600">{{ t('marketplace.submitFailed') }}</p><button class="btn-primary" :disabled="readOnly || !options || !provider || busy || conflict || !valid">{{ t('marketplace.save') }}</button></form><div class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.actions') }}</h2><p class="text-sm text-gray-500">{{ t('marketplace.probeExplanation') }}</p><div class="flex flex-wrap gap-2"><button v-if="['draft', 'rejected'].includes(account.offer.review_status) && !readOnly" class="btn-secondary" :disabled="busy" @click="confirmAction('submit')">{{ t('marketplace.submitReview') }}</button><button v-if="account.offer.enabled" class="btn-secondary" :disabled="busy" @click="confirmAction('pause')">{{ t('marketplace.pause') }}</button><button v-else-if="account.offer.review_status === 'approved' && !readOnly" class="btn-secondary" :disabled="busy" @click="confirmAction('resume')">{{ t('marketplace.resume') }}</button><button class="btn-secondary" :disabled="busy" @click="performProbe">{{ t('marketplace.probe') }}</button><button v-if="account.offer.review_status !== 'revoked'" class="btn-secondary text-red-600" :disabled="busy" @click="confirmAction('revoke')">{{ t('marketplace.revoke') }}</button></div><p v-if="probeResult" role="status" class="text-sm">{{ probeResult }}</p></div></template><ConfirmDialog :show="!!action" :title="t(`marketplace.${action || 'pause'}`)" :message="t(`marketplace.${action || 'pause'}Explanation`)" :danger="action === 'revoke'" @cancel="action = null" @confirm="perform" /></div></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, nextTick, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import ConfirmDialog from '@/components/common/ConfirmDialog.vue'
import AccountConcurrencyForm from '@/components/supplier/AccountConcurrencyForm.vue'
import { getAccount, getSupplierOptions, updateAccount, accountAction } from '@/api/supplier'
import { useWorkModeStore } from '@/stores/workMode'
import type { SupplierAccount, SupplierOptions } from '@/types/marketplace'
const { t } = useI18n(); const route = useRoute(); const store = useWorkModeStore(); const account = ref<SupplierAccount | null>(null); const options = ref<SupplierOptions | null>(null); const name = ref(''); const models = ref<string[]>([]); const concurrency = ref(1); const loading = ref(true); const error = ref(false); const conflict = ref(false); const busy = ref(false); const probeResult = ref(''); const action = ref<'submit' | 'pause' | 'resume' | 'revoke' | null>(null)
const readOnly = computed(() => store.capabilities?.supplier_status === 'suspended'); const provider = computed(() => options.value?.providers?.find(p => p.platform === account.value?.platform)); const valid = computed(() => !!name.value.trim() && models.value.length > 0 && Number.isInteger(concurrency.value) && concurrency.value > 0 && concurrency.value <= (options.value?.max_supplier_concurrency || 0))
watch([name, models, concurrency], () => { if (!loading.value) store.dirty = true }, { deep: true })
async function load() { loading.value = true; error.value = false; try { const [a, o] = await Promise.all([getAccount(Number(route.params.id)), getSupplierOptions().catch(() => null)]); account.value = a; options.value = o; name.value = a.name; models.value = [...a.offer.allowed_models]; concurrency.value = a.concurrency; await nextTick(); store.dirty = false } catch { error.value = true } finally { loading.value = false } }
async function refreshVersion() { try { const latest = await getAccount(Number(route.params.id)); account.value = latest; conflict.value = false } catch { error.value = true } }
async function save() { if (!account.value || !valid.value || busy.value || readOnly.value || conflict.value) return; busy.value = true; error.value = false; try { account.value = await updateAccount(account.value.id, { expected_version: account.value.offer.version, name: name.value.trim(), concurrency: concurrency.value, allowed_models: models.value }); store.dirty = false } catch (e) { if ((e as { status?: number }).status === 409) conflict.value = true; else error.value = true } finally { busy.value = false } }
async function confirmAction(kind: 'submit' | 'pause' | 'resume' | 'revoke') { if (await store.confirmLeave()) action.value = kind }
async function perform() { if (!account.value || !action.value || busy.value) return; busy.value = true; try { await accountAction(account.value.id, action.value, account.value.offer.version); action.value = null; await load() } catch (e) { action.value = null; if ((e as { status?: number }).status === 409) conflict.value = true; else error.value = true } finally { busy.value = false } }
async function performProbe() { if (!account.value || busy.value) return; busy.value = true; probeResult.value = ''; try { await accountAction(account.value.id, 'probe', account.value.offer.version); probeResult.value = t('marketplace.probeComplete') } catch { probeResult.value = t('marketplace.probeFailed') } finally { busy.value = false } }
onMounted(load); onUnmounted(() => { store.dirty = false })
</script>
